records = [('Anna', 95), ('Ben', 82), ('Cara', 76), ('Dan', 61), ('Eve', 54)]
def get_grade(score):
    if score >= 90:
        return 'A'
    elif score >= 80:
        return 'B'
    elif score >= 70:
        return 'C'
    elif score >= 60:
        return 'D'
    else:
        return 'F'
result = {name: get_grade(score) for name, score in records}
print(result)
